Compose_Task_Acknowledgement_Link.inputs:
@concat(
  'https://taskack.page.gd/index.html',
  '?item=', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)),
  '&name=', uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
  ),
  '&email=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=', uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task')?['body/Title'], '')), '\n', ' '), '\r', ' '))
  ),
  '&ref=', uriComponent(
    concat('TASK-', string(coalesce(outputs('Get_item_Task')?['body/ID'], 0)))
  )
)

Compose_PreheaderText.inputs:
@concat(
  'Assignment notification for ',
  outputs('Compose_Subject_Email'),
  '. Acknowledge and review.'
)

Compose_Email__CC.inputs:
@if(
  empty(
    trim(
      replace(
        replace(
          coalesce(triggerBody()?['NewActivityTask']?['supportingAssignedTo'], ''),
          decodeUriComponent('%0D'),
          ''
        ),
        decodeUriComponent('%0A'),
        ''
      )
    )
  ),
  '',
  trim(
    replace(
      replace(
        coalesce(triggerBody()?['NewActivityTask']?['supportingAssignedTo'], ''),
        decodeUriComponent('%0D'),
        ''
      ),
      decodeUriComponent('%0A'),
      ''
    )
  )
)

Compose_Email_To.inputs:
@if(
  and(
    not(empty(outputs('Compose_Clean_AssignedTo'))),
    not(empty(outputs('Compose_Clean_Assigned')))
  ),
  concat(
    outputs('Compose_Clean_AssignedTo'),
    ';',
    outputs('Compose_Clean_Assigned')
  ),
  if(
    not(empty(outputs('Compose_Clean_AssignedTo'))),
    outputs('Compose_Clean_AssignedTo'),
    outputs('Compose_Clean_Assigned')
  )
)

Compose_PriorityText.inputs:
@if(
  or(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'critical'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'urgent'),
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'high')
  ),
  'Priority Review Window',
  if(
    contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Category'], 'general'))),'confidential'),
    'Restricted Executive Dispatch',
    'Standard Official Review'
  )
)

Compose_Handling_Status.inputs:
@if(
  contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Category'], 'general'))),'confidential'),
  'Restricted Circulation',
  if(
    or(
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'critical'),
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'urgent'),
      contains(toLower(string(coalesce(triggerBody()?['NewActivityTask']?['Priority'], 'normal'))),'high')
    ),
    'Expedited Review',
    'Standard Official Review'
  )
)

Compose_BulkPreheader.inputs:
@concat(
  'Assignment notification for ',
  outputs('Compose_Subject_Email'),
  '. Acknowledge and review.'
)

parameters.emailMessage/Subject:
Web - Subsidiary Doc Actions_ @{concat(
  'NITDA AUDIT | Single Task Assignment | ',
  if(less(coalesce(variables('varStatusCode'), 0), 400), 'SUCCESS', 'FAILED'),
  ' | ',
  trim(
    replace(
      replace(
        coalesce(
          triggerBody()?['NewActivityTask']?['Title'],
          'Single_Create_Task_Assignment'
        ),
        decodeUriComponent('%0D'),
        ''
      ),
      decodeUriComponent('%0A'),
      ''
    )
  ),
  ' | ReqId: ',
  if(
    empty(trim(coalesce(triggerBody()?['requestId'], ''))),
    variables('varRequestId'),
    triggerBody()?['requestId']
  ),
  ' | RunId: ',
  workflow()?['run']?['name']
)}
